static void dom_copy_prop_handler(zval *zv) /* {{{ */
{
        dom_prop_handler *hnd = Z_PTR_P(zv);
        Z_PTR_P(zv) = malloc(sizeof(dom_prop_handler));
        memcpy(Z_PTR_P(zv), hnd, sizeof(dom_prop_handler));
}
